#include <iostream>
#include <stdexcept>
using namespace std;

int countFish(int n) {
    if (n < 0) {
        throw runtime_error("鱼干数不能是负数喵");
    }
    return n * 2;
}

int main() {
    try {
        cout << countFish(3) << endl;
        cout << countFish(-1) << endl;
        cout << "这一句不会印出来" << endl;
    } catch (const runtime_error& e) {
        cout << "接住了：" << e.what() << endl;
    }
    return 0;
}
